R=Path('Code2');C=R/'Code2.cpp';L=R/'RESIDUAL_LEDGER.md';P=R/'PROGRESS.md';A=R/'CODE2_CONTINUITY_ADDENDUM.md';K=R/'RESUME_CHECKPOINT.md';F=R/'.batch91.fragment.cpp'
